package example;

import java.util.List;
import java.util.Map;

public class PaymentService {
    private final List<String> paymentMethods = List.of("credit_card", "debit_card", "paypal");

    public boolean processPayment(String method, double amount) {
        if (!paymentMethods.contains(method)) {
            throw new IllegalArgumentException("Invalid payment method: " + method);
        }
        return amount > 0;
    }

    public Map<String, String> getPaymentInfo() {
        return Map.of(
            "methods", paymentMethods.toString(),
            "supported_currencies", "USD,EUR"
        );
    }
}
