package example;

import java.math.BigDecimal;
import java.util.List;

public class PaymentService {
    private final List<String> paymentMethods = List.of("credit_card", "debit_card", "paypal");

    public BigDecimal calculateTotal(List<PaymentItem> items) {
        return items.stream()
                   .mapToDouble(PaymentItem::getAmount)
                   .sum();
    }

    public boolean validatePaymentMethod(String method) {
        return paymentMethods.contains(method);
    }
}
